function planningSnapshot() {
  const capture = PLANNING_CAPTURE;
  assert.ok(capture.bytes <= 1800000 && capture.compressed_bytes <= 524288);
  assert.match(capture.data, /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/);
  const compressed = Buffer.from(capture.data, 'base64');
  assert.equal(compressed.toString('base64'), capture.data);
  assert.equal(compressed.length, capture.compressed_bytes); assert.equal(h.hash(compressed), capture.compressed_sha256);
  const bytes = require('node:zlib').gunzipSync(compressed, { maxOutputLength: capture.bytes });
  assert.equal(bytes.length, capture.bytes); assert.equal(h.hash(bytes), capture.sha256);
  const entries = JSON.parse(bytes), result = new Map();
  assert.equal(entries.length, 39);
  for (const entry of entries) {
    assert.deepEqual(Object.keys(entry).sort(), ['bytes', 'content', 'path', 'sha256']);
    assert.ok(entry.path.startsWith('.planning/') && !entry.path.split('/').includes('..'));
    assert.equal(result.has(entry.path), false);
    assert.ok(Number.isSafeInteger(entry.bytes) && entry.bytes <= 441898);
    assert.equal(Buffer.byteLength(entry.content), entry.bytes); assert.equal(h.hash(entry.content), entry.sha256);
    result.set(entry.path, entry);
  }
  assert.equal(result.get('.planning/phases/53-simplify-delivery-process/53-35-PLAN.md').sha256,
    'f16553330a3ce8375dd39d58581a71a88fa4dad0091315db1906694a765b80d1');
  const current = CURRENT_PLANNING_CAPTURE, compressedCurrent = Buffer.from(current.data, 'base64');
  assert.ok(current.bytes <= 110000 && current.compressed_bytes <= 65536);
  assert.equal(compressedCurrent.toString('base64'), current.data);
  assert.equal(compressedCurrent.length, current.compressed_bytes); assert.equal(h.hash(compressedCurrent), current.compressed_sha256);
  const decoded = require('node:zlib').gunzipSync(compressedCurrent, { maxOutputLength: current.bytes });
  assert.equal(decoded.length, current.bytes); assert.equal(h.hash(decoded), current.sha256);
  const additions = JSON.parse(decoded); assert.equal(additions.length, 2);
  for (const [index, entry] of additions.entries()) {
    assert.deepEqual(Object.keys(entry).sort(), ['bytes', 'content', 'path', 'sha256']);
    assert.equal(entry.path, '.planning/phases/53-simplify-delivery-process/53-' + (35 + index) + '-PLAN.md');
    assert.ok(entry.bytes <= 65536); assert.equal(Buffer.byteLength(entry.content), entry.bytes);
    assert.equal(h.hash(entry.content), entry.sha256); result.set(entry.path, entry);
  }
  assert.equal(result.get('.planning/phases/53-simplify-delivery-process/53-35-PLAN.md').sha256,
    '09402d919176a17e8bfbbc5e354333b2671bae19900f313e586b91d07d1a8428');
  assert.equal(result.get('.planning/phases/53-simplify-delivery-process/53-36-PLAN.md').sha256,
    '41079298fd68156965c2e7b47fef417e675a694da13c30288faee6919e6ab277');
  return result;
}
