function sourceSelector(plugin = path.dirname(h.SCRIPTS)) {
  const file = path.join(plugin, 'scripts/codex-code-review-context.cjs'), loaded = new Module(file, module);
  loaded.filename = file; loaded.paths = Module._nodeModulePaths(path.dirname(file));
  loaded._compile(fs.readFileSync(file, 'utf8') + '\nmodule.exports = { selectProductSources };', file);
  return packet => {
    const contents = new Map(packet.product_source_contents.map(entry => [entry.sha256, entry]));
    delete packet.product_source_format; delete packet.product_source_contents;
    loaded.exports.selectProductSources(packet, contents);
    return packet;
  };
}
function inlineSources(packet) {
  const contents = new Map(packet.product_source_contents.map(entry => [entry.sha256, entry.content]));
  const result = h.clone(packet);
  result.product_sources = packet.product_sources.map(({ path, revision, bytes, sha256 }) =>
    ({ path, revision, content: contents.get(sha256), bytes, sha256 }));
  delete result.product_source_format; delete result.product_source_contents;
  return result;
}
